toad_implementation.code_blueprint:
canvas {
  size: 700px 950px;
  fill: #141113;
  font-family: "Didot, serif";
}

>velvet = #141113;
>porcelain = #E5C3B2;
>bronze = #8C5849;
>silkWhite = #FFF5EE;

rect #photoCard {
  at: center of canvas;
  size: 580px 820px;
  fill: #1E1A1D;
  stroke: >bronze;
  stroke-width: 1px;
}

circle #beautyLight {
  at: center of #photoCard offset 0px -80px;
  size: 320px;
  fill: alpha(>porcelain, 0.28);
}

rect #portraitMask {
  at: center of #photoCard offset 0px -40px;
  size: 360px 480px;
  fill: none;
  stroke: >porcelain;
  stroke-width: 1.5px;
  radius: 180px;
}

text #coverTitle {
  at: below #portraitMask offset 60px;
  content: "S E R A P H I C";
  font-size: 32px;
  font-weight: 700;
  color: >silkWhite;
}

text #subHeader {
  at: below #coverTitle offset 14px;
  content: "AUTUMN HAUTE BEAUTÉ COLLECTION";
  font-size: 11px;
  color: >porcelain;
}
